+}
+.breadcrumb a:hover { color: var(--color-text); text-decoration: underline; }
+.breadcrumb a:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 2px;
+  border-radius: 2px;
+}
+.breadcrumb .sep { color: var(--color-border); font-size: .875rem; }
+.breadcrumb .current { color: var(--color-text); font-size: .875rem; }
