+  display: flex;
+  align-items: center;
+  justify-content: center;
+  color: var(--color-danger);
+}
+
+.dialog-title-group { flex: 1; }
+.dialog-title {
+  font-size: 1.0625rem;
+  font-weight: 600;
+  line-height: 1.3;
+  margin-bottom: .25rem;
+}
+.dialog-desc {
+  font-size: .875rem;
+  color: var(--color-text-muted);
+  line-height: 1.55;
+}
+
+.dialog-thumbnail {
+  display: flex;
+  align-items: center;
+  gap: .875rem;
+  background: var(--color-surface-raise);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-md);
+  padding: .75rem;
+  margin-bottom: 1.25rem;
+}
+.dialog-thumbnail img {
+  width: 52px;
+  height: 52px;
+  border-radius: var(--radius-sm);
+  object-fit: cover;
+  flex-shrink: 0;
+}
+.dialog-thumb-info { min-width: 0; }
+.dialog-thumb-name {
+  font-size: .875rem;
+  font-weight: 500;
+  overflow: hidden;
+  white-space: nowrap;
+  text-overflow: ellipsis;
+}
+.dialog-thumb-size { font-size: .75rem; color: var(--color-text-muted); margin-top: .15rem; }
+
+.dialog-warning {
+  font-size: .8125rem;
+  color: var(--color-text-muted);
+  background: rgba(224,85,85,.07);
+  border: 1px solid rgba(224,85,85,.2);
+  border-radius: var(--radius-sm);
+  padding: .6rem .875rem;
+  margin-bottom: 1.5rem;
+  line-height: 1.5;
+}
+
+.dialog-footer {
+  display: flex;
+  gap: .625rem;
+  justify-content: flex-end;
+  flex-wrap: wrap;
+}
+.dialog-footer .btn { flex: 1; justify-content: center; min-width: 100px; }
+
+/* ── Close button ── */
+.dialog-close {
+  position: absolute;
+  top: 1rem;
+  right: 1rem;
+  background: transparent;
+  border: none;
+  color: var(--color-text-muted);
+  cursor: pointer;
+  border-radius: var(--radius-sm);
+  padding: .25rem;
+  display: flex;
+  transition: color var(--transition), background var(--transition);
