  const closeBtn   = backdropEl.querySelector('.dialog-close');
  const cancelBtn  = backdropEl.querySelector('.js-cancel');
  const confirmBtn = backdropEl.querySelector('.js-confirm');
  const liveRegion = document.getElementById('live-region');

  const trap = createFocusTrap(dialogEl);
  let triggerEl = null; // element that opened the dialog

  function open(opener) {
    triggerEl = opener;
    backdropEl.classList.add('is-open');
    backdropEl.removeAttribute('aria-hidden');
    dialogEl.removeAttribute('inert');
    trap.activate();
    // Move focus to first focusable element in dialog
    const first = dialogEl.querySelector(
      'button:not([disabled]), [tabindex]:not([tabindex="-1"])'
    );
    if (first) first.focus();
  }

  function close() {
    backdropEl.classList.remove('is-open');
    backdropEl.setAttribute('aria-hidden', 'true');
    dialogEl.setAttribute('inert', '');
    trap.deactivate();
    if (triggerEl) triggerEl.focus();
  }

  function handleConfirm() {
    close();
    if (typeof onConfirm === 'function') onConfirm();
    // Announce result to screen readers
    liveRegion.textContent = '';
    requestAnimationFrame(() => {
      liveRegion.textContent = 'Image deleted from your library.';
    });
  }

  // Close on backdrop click (but not on dialog itself)
  backdropEl.addEventListener('click', (e) => {
    if (e.target === backdropEl) close();
  });

  // Close on Escape
  backdropEl.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') { e.preventDefault(); close(); }
  });

  closeBtn.addEventListener('click',   close);
  cancelBtn.addEventListener('click',  close);
  confirmBtn.addEventListener('click', handleConfirm);

  return { open, close };
}

